    double req[3];
    double raw[3];
    double lim[3];
    size_t i;

    if ((requested == NULL) || (area_turns == NULL) || (resistance == NULL) ||
        (voltage_limit == NULL) || (voltage == NULL) || (realized == NULL) || (mask == NULL)) {
        if (voltage != NULL) {
            *voltage = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
        if (realized != NULL) {
            *realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
        if (mask != NULL) {
            *mask = 0U;
        }
        return ADCS_E_NULL;
    }

    req[0] = requested->x;
    req[1] = requested->y;
    req[2] = requested->z;

    for (i = 0; i < 3U; i++) {
        if ((!isfinite(req[i])) || (!isfinite(area_turns[i])) || (area_turns[i] <= 0.0) ||
            (!isfinite(resistance[i])) || (resistance[i] <= 0.0) || (!isfinite(voltage_limit[i])) ||
            (voltage_limit[i] < 0.0)) {
            *voltage = (adcs_vec3_t){0.0, 0.0, 0.0};
            *realized = (adcs_vec3_t){0.0, 0.0, 0.0};
            *mask = 0U;
            return ADCS_E_RANGE;
        }
    }

    *mask = 0U;

    for (i = 0; i < 3U; i++) {
        raw[i] = resistance[i] * req[i] / area_turns[i];
        lim[i] = voltage_limit[i];
        if (raw[i] > lim[i]) {
            raw[i] = lim[i];
            *mask |= (unint32)(1U << i);
        } else if (raw[i] < -lim[i]) {
            raw[i] = -lim[i];
            *mask |= (unint32)(1U << i);
        }
    }

    voltage->x = raw[0];
    voltage->y = raw[1];
    voltage->z = raw[2];
    realized->x = voltage->x * area_turns[0] / resistance[0];
    realized->y = voltage->y * area_turns[1] / resistance[1];
    realized->z = voltage->z * area_turns[2] / resistance[2];

    return ADCS_OK;
}

